<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import type { AnalyticsClient, ExportResult, LoadStatisticsResult } from './client';
import { isAccessFailure, moneyText, problemCode, problemText, utcInput } from './client';
const props = defineProps<{ client: AnalyticsClient; parentSignal: AbortSignal }>();
const end = new Date(); end.setUTCMinutes(0, 0, 0); const start = new Date(end.getTime() - 7 * 86400000);
const from = ref(start.toISOString().slice(0, 16)); const to = ref(end.toISOString().slice(0, 16));
const result = ref<LoadStatisticsResult>(); const busy = ref(false); const message = ref(''); const page = ref(0); const exportBusy = ref(false); const exported = ref<ExportResult>(); const operation = ref('');
let exportRequest: AbortController | undefined; let lastExportKind = ''; let request: AbortController | undefined; const lifetime = new AbortController(); props.parentSignal.addEventListener('abort', () => { lifetime.abort(); request?.abort(); exportRequest?.abort(); }, { once: true, signal: lifetime.signal });
const visibleRows = computed(() => result.value?.rows.slice(page.value * 100, (page.value + 1) * 100) ?? []);
function clearOverview(): void { request?.abort(); exportRequest?.abort(); result.value = undefined; exported.value = undefined; operation.value = ''; busy.value = false; exportBusy.value = false; }
async function loadOverview(): Promise<void> { clearOverview(); const current = new AbortController(); request = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); busy.value = true; message.value = ''; try { const data = await props.client.LoadStatistics({ from: utcInput(from.value), to: utcInput(to.value) }, current.signal); if (!current.signal.aborted) { result.value = data; page.value = 0; } } catch (error) { if (!current.signal.aborted) { result.value = undefined; message.value = problemText(error); } } finally { if (request === current && !lifetime.signal.aborted) busy.value = false; } }
async function exportOverviewCSV(kind: 'pages' | 'usage'): Promise<void> { if (!result.value || exportBusy.value) return; const data = result.value; const current = new AbortController(); exportRequest?.abort(); exportRequest = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); exportBusy.value = true; message.value = ''; if (!operation.value || lastExportKind !== kind) { operation.value = crypto.randomUUID(); lastExportKind = kind; } try { const value = await props.client.RequestExport({ kind, from: data.fromUTC, to: data.toUTC, operationId: operation.value }, current.signal); if (!current.signal.aborted) exported.value = value; } catch (error) { if (!current.signal.aborted) { if (isAccessFailure(error)) clearOverview(); if (problemCode(error) === 'GONE') { exported.value = undefined; operation.value = ''; } message.value = problemText(error); } } finally { if (exportRequest === current && !lifetime.signal.aborted) exportBusy.value = false; } }
async function downloadOverviewCSV(): Promise<void> { if (!exported.value || exportBusy.value) return; const value = exported.value; const current = new AbortController(); exportRequest?.abort(); exportRequest = current; lifetime.signal.addEventListener('abort', () => current.abort(), { once: true, signal: current.signal }); exportBusy.value = true; try { await props.client.DownloadAuthorizedExport({ exportId: value.exportId, kind: value.kind }, current.signal); } catch (error) { if (!current.signal.aborted) { if (isAccessFailure(error)) clearOverview(); if (problemCode(error) === 'GONE') { exported.value = undefined; operation.value = ''; } message.value = problemText(error); } } finally { if (exportRequest === current && !lifetime.signal.aborted) exportBusy.value = false; } }
onMounted(loadOverview); onBeforeUnmount(() => { lifetime.abort(); request?.abort(); exportRequest?.abort(); result.value = undefined; exported.value = undefined; });
</script>
<template>
  <section class="analytics-panel"><h2>访问与费用投影</h2><p class="muted">费用仅为已观测账项的派生统计，不是实时余额。访次在每个小时内去重，跨小时相加不代表独立访客。</p>
    <form class="filters" @submit.prevent="loadOverview"><label>起点（UTC整点）<input v-model="from" type="datetime-local" step="3600" required @change="clearOverview"></label><label>终点（UTC整点，不含）<input v-model="to" type="datetime-local" step="3600" required @change="clearOverview"></label><button :disabled="busy">{{ busy ? '读取中…' : '载入统计' }}</button></form>
    <p v-if="message" role="alert">{{ message }}</p><p v-if="busy" role="status">正在读取已保存统计…</p>
    <template v-if="result"><div class="summary"><span>访问水位 {{ result.watermark }}</span><span>累计漏数 {{ result.dropCount }}</span><template v-if="result.usage"><strong>{{ moneyText(result.usage.amountMicros) }}</strong><span>费用水位 {{ result.usage.watermark }}</span><span>最后完整对账：{{ result.usage.lastReconciledAt || '尚未完成' }}</span></template><span v-else>费用投影暂不可用，访问数据已保留。</span></div>
      <div class="actions"><button :disabled="exportBusy" @click="exportOverviewCSV('pages')">导出访问CSV</button><button :disabled="exportBusy || !result.usage" @click="exportOverviewCSV('usage')">导出费用CSV</button><button v-if="exported" :disabled="exportBusy" @click="downloadOverviewCSV">下载已封存CSV</button><small v-if="exported">到期 {{ exported.expiresAt }} · 水位 {{ exported.watermark }}</small></div>
      <p v-if="!result.rows.length" class="muted">该区间没有已完成聚合的访问行。</p><div v-else class="table-scroll"><table><thead><tr><th>小时（UTC）</th><th>文档</th><th>语言</th><th>PV</th><th>分桶访次</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.periodStart + row.documentId + row.locale"><td>{{ row.periodStart }}</td><td>{{ row.documentId }}</td><td>{{ row.locale }}</td><td>{{ row.views }}</td><td>{{ row.visits }}</td></tr></tbody></table></div>
      <nav v-if="result.rows.length > 100" aria-label="访问表分页"><button :disabled="page === 0" @click="page--">上一页</button><span>第 {{ page + 1 }} 页，共 {{ Math.ceil(result.rows.length / 100) }} 页</span><button :disabled="(page + 1) * 100 >= result.rows.length" @click="page++">下一页</button></nav>
    </template>
  </section>
</template>
